import{_ as o,a0 as n,w as p,s as d,ao as h,I as t,x as e,a1 as a,A as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"在 Linux 中移除从源代码安装的程序的一种简单的方法 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 中移除从源代码安装的程序的一种简单的方法 | LCTT (201901) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 中移除从源代码安装的程序的一种简单的方法 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 中移除从源代码安装的程序的一种简单的方法 | LCTT (201901) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201901/20181221 An Easy Way To Remove Programs Installed From Source In Linux","title":"在 Linux 中移除从源代码安装的程序的一种简单的方法","tag":"201901","desc":""},"relativePath":"201901/20181221 An Easy Way To Remove Programs Installed From Source In Linux.md","filePath":"[post].md"}'),r={name:"201901/20181221 An Easy Way To Remove Programs Installed From Source In Linux.md"};function c(g,s,u,k,b,f){const i=n("Link");return p(),d("div",null,[s[15]||(s[15]=h(`<h1 id="在-linux-中移除从源代码安装的程序的一种简单的方法" tabindex="-1">在 Linux 中移除从源代码安装的程序的一种简单的方法 <a class="header-anchor" href="#在-linux-中移除从源代码安装的程序的一种简单的方法" aria-label="Permalink to “在 Linux 中移除从源代码安装的程序的一种简单的方法”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/12/stow-1-720x340.jpg" alt=""></p><p>不是所有的程序都可以在官方或者第三方库中找到，因此你不能使用常规的包管理来安装它们。有时你不得不从源代码中手动构建这些程序。就如你已经知道的一样，当你从源代码中安装一个程序的时候，这个软件包所包含的文件将会复制到本地的多个位置，例如 <code>/usr/local/bin</code>、<code>/usr/local/etc/</code>。如果从源代码中安装的程序没有内置的卸载程序，当你不再需要这个程序的时候，卸载它就会很麻烦。你可能会花费双倍（甚至更多）的时间找出这些文件然后手动删除它们。我以前一直是这样做的，直到我发现了 GNU Stow。谢天谢地，Stow 有一个很棒的方法可以轻松管理从源代码安装的程序。</p><p>引用官方网站里的一段介绍，</p><blockquote><p>GNU Stow 是一个符号链接归集管理器，它可以收集文件系统上不同目录中的不同软件和/或数据包，使它们看起来像是一个整体。</p></blockquote><p>简单来说，Stow 帮助你把这些程序文件以一种容易管理的方式组织在了一起。在这个方法中，文件将不会被复制到多个位置。所有的这些文件都会被保存在一个特定的文件夹中，通常是以程序名命名的，然后 Stow 会在一个合适的位置为所有的程序文件创建符号连接。比如 <code>/usr/local/bin</code> 中会包含 <code>/usr/local/stow/vim/bin</code>、<code>/usr/local/stow/python/bin</code> 中文件的符号链接。并且同样递归地用于其他的任何的子目录，例如 <code>.../share</code>、<code>.../man</code>，等等。在这篇教程中，我将会举例教你如何轻松地使用 Stow 管理从源中安装的程序。</p><h3 id="安装-gnu-stow" tabindex="-1">安装 GNU Stow <a class="header-anchor" href="#安装-gnu-stow" aria-label="Permalink to “安装 GNU Stow”">​</a></h3><p>GNU Stow 在流行 Linux 操作系统的默认库中都可用。</p><p>在 Arch Linux 及它的衍生版本中，运行下面的命令安装 Stow。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo pacman -S stow</span></span></code></pre></div><p>在 Debian、Ubuntu、Linux Mint 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install stow</span></span></code></pre></div><p>在 Fedora 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install stow</span></span></code></pre></div><p>在 RHEL/CentOS 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo yum install epel-release</span></span>
<span class="line"><span>$ sudo yum install stow</span></span></code></pre></div><h3 id="在-linux-上轻松移除从源代码安装的程序" tabindex="-1">在 Linux 上轻松移除从源代码安装的程序 <a class="header-anchor" href="#在-linux-上轻松移除从源代码安装的程序" aria-label="Permalink to “在 Linux 上轻松移除从源代码安装的程序”">​</a></h3><p>就像我之前提到的，所有包的程序文件都将被保存在位于 <code>/usr/local/stow/</code> 的一个根文件夹。在这个根文件夹或者父目录之下，每个包都将保存在对应的子目录中。例如，如果我们从源代码中安装了 Vim 编辑器，所有关联到 Vim 的程序文件和目录都将保存在 <code>/usr/local/stow/vim</code> 文件夹之下。如果你从源代码中安装了 Python，所有关联到 python 的文件都会保存在 <code>/usr/local/stow/python</code> 之下。</p><p>我现在从源代码中来安装一个叫做 hello 的程序。</p><p>首先下载 hello 程序的压缩包。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ wget http://ftp.gnu.org/gnu/hello/hello-2.10.tar.gz</span></span></code></pre></div><p>使用下面的命令解压压缩包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tar -zxvf hello-2.10.tar.gz</span></span></code></pre></div><p>上面的命令将会在当前工作目录下创建一个叫做 <code>hello-2.10</code> 的目录，并且提取压缩包中的所有内容到其中去。</p><p>切换到这个目录当中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd hello-2.10/</span></span></code></pre></div><p>运行下面的命令，并且添加 <code>-prefix</code> 选项。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ./configure --prefix=/usr/local/stow/hello</span></span></code></pre></div><p>上面的命令将会保存构建文件到一个指定位置，在这个例子中是 <code>/usr/local/stow/hello</code>。</p><p>最后，使用下面的命令构建并安装 hello 这个程序：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ make</span></span>
<span class="line"><span>$ sudo make install</span></span></code></pre></div><p>就这样。hello 这个程序就已经安装在 <code>/usr/local/stow/hello/</code> 这个位置了。你可以使用下面的 <code>ls</code> 命令确认一下。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls /usr/local/stow/hello/</span></span>
<span class="line"><span>bin share</span></span></code></pre></div><p>最后，进入 <code>/usr/local/stow/</code> 目录，运行下面的命令来生成必要的符号链接。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd /usr/local/stow/</span></span>
<span class="line"><span>$ sudo stow hello</span></span></code></pre></div><p>大功告成！</p><p>刚才那一步是将包含在 hello 这个程序中的所有文件或者目录创建了链接到 <code>/usr/local/</code> 目录中。换一种说法， <code>/usr/local/stow/hello/bin</code> 链接到 <code>/usr/local/share</code>，以及 <code>/usr/local/stow/hello/share/man</code> 链接到 <code>/usr/local/share</code>，还有 <code>/usr/local/stow/hello/share/man</code> 链接到 <code>/usr/local/share/man</code>。</p><p>你可以使用 <code>ls</code> 命令来确认一下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls /usr/local/bin/</span></span>
<span class="line"><span>hello</span></span></code></pre></div><p>可以使用下面的命令来确认 hello 这个程序是否可以正常工作了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ hello</span></span>
<span class="line"><span>Hello, world!</span></span></code></pre></div><p>很好，它已经开始工作了！！</p><p>类似地，你可以像上面描述的那样安装程序到它对应的子目录下。</p><p>下面是 Stow 根目录包含的内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tree /usr/local/stow/</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/12/tree-command.png" alt=""></p><p>看，hello 这个程序已经安装在 <code>/usr/local/stow/hello/</code> 下。同样地，所有的包都将保存在它们对应的目录之下。</p><p>下面进入主要环节，移除 hello 这个程序。首先进入 <code>/usr/local/stow/</code> 目录：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd /usr/local/stow/</span></span></code></pre></div><p>然后运行下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo stow --delete hello</span></span></code></pre></div><p>hello 这个程序就会被移除了。你可以使用下面的命令确认它是否真的被移除了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ hello</span></span>
<span class="line"><span>-bash: /usr/local/bin/hello: No such file or directory</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/12/hello-world.png" alt=""></p><p>看， Hello 已经被移除了！</p><p>请注意 Stow 仅仅只移除了符号链接。所有与 hello 这个程序相关的文件或者目录还保存在 <code>/usr/local/stow/hello</code> 目录下。所以你无需再次下载源文件就可以再次安装 hello 这个程序。如果你不再需要它了，直接删除这个文件夹即可。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo rm -fr /usr/local/stow/hello/</span></span></code></pre></div><p>想了解更多 Stow 的细节，请参阅 man 手册。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man stow</span></span></code></pre></div><p>Stow 可以像安装程序一样轻松地帮你移除它。如果你想知道如何高效的管理很多从源代码中安装的程序，GNU Stow 就是一个使得这个任务更加轻松的一个选择，尝试一下，你一定不会失望的。</p><p>这就是所有的内容了，希望对你有所帮助。还有更多干活即将到来，可以期待一下的！</p><p>祝近祺！</p><hr>`,63)),t("p",null,[s[1]||(s[1]=e("via: ",-1)),a(i,{href:"https://www.ostechnix.com/an-easy-way-to-remove-programs-installed-from-source-in-linux/"},{default:l(()=>[...s[0]||(s[0]=[e("https://www.ostechnix.com/an-easy-way-to-remove-programs-installed-from-source-in-linux/",-1)])]),_:1})]),t("p",null,[s[6]||(s[6]=e("作者：",-1)),a(i,{href:"https://www.ostechnix.com/author/sk/"},{default:l(()=>[...s[2]||(s[2]=[e("SK",-1)])]),_:1}),s[7]||(s[7]=e(" 选题：",-1)),a(i,{href:"https://github.com/lujun9972"},{default:l(()=>[...s[3]||(s[3]=[e("lujun9972",-1)])]),_:1}),s[8]||(s[8]=e(" 译者：",-1)),a(i,{href:"https://github.com/dianbanjiu"},{default:l(()=>[...s[4]||(s[4]=[e("dianbanjiu",-1)])]),_:1}),s[9]||(s[9]=e(" 校对：",-1)),a(i,{href:"https://github.com/wxy"},{default:l(()=>[...s[5]||(s[5]=[e("wxy",-1)])]),_:1})]),t("p",null,[s[12]||(s[12]=e("本文由 ",-1)),a(i,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[10]||(s[10]=[e("LCTT",-1)])]),_:1}),s[13]||(s[13]=e(" 原创编译，",-1)),a(i,{href:"https://linux.cn/"},{default:l(()=>[...s[11]||(s[11]=[e("Linux中国",-1)])]),_:1}),s[14]||(s[14]=e(" 荣誉推出",-1))])])}const x=o(r,[["render",c]]);export{w as __pageData,x as default};
